import { ITodoTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoTodo";
import { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function postTodoUserTodos(props: {
  user: UserPayload;
  body: ITodoTodo.ICreate;
}): Promise<ITodoTodo> {
  const now = toISOStringSafe(new Date());
  const completion = props.body.status === "complete" ? now : null;

  const created = await MyGlobal.prisma.todo_todos.create({
    data: {
      id: v4(),
      title: props.body.title,
      description:
        props.body.description === undefined ? null : props.body.description,
      status: props.body.status,
      todo_user_id: props.user.id,
      created_at: now,
      updated_at: now,
      completed_at: completion,
    },
    include: {
      user: true,
    },
  });

  return {
    id: created.id,
    title: created.title,
    description: created.description ?? undefined,
    status: typia.assert<"incomplete" | "complete">(created.status),
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    completed_at:
      created.completed_at !== null && created.completed_at !== undefined
        ? toISOStringSafe(created.completed_at)
        : undefined,
    user: {
      id: created.user.id,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoTodo";
import { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function putTodoUserTodosTodoId(props: {
  user: UserPayload;
  todoId: string & tags.Format<"uuid">;
  body: ITodoTodo.IUpdate;
}): Promise<ITodoTodo> {
  // 1. Check todo existence & ownership
  const todo = await MyGlobal.prisma.todo_todos.findUnique({
    where: { id: props.todoId },
  });
  if (!todo || todo.todo_user_id !== props.user.id) {
    throw new HttpException("Todo not found", 404);
  }

  // 2. Prepare fields
  const now = toISOStringSafe(new Date());
  const isCompleting = props.body.status === "complete";
  let completed_at: (string & tags.Format<"date-time">) | null = null;
  if (isCompleting) {
    completed_at = todo.completed_at
      ? typeof todo.completed_at === "string"
        ? todo.completed_at
        : toISOStringSafe(todo.completed_at)
      : now;
  }
  if (props.body.status === "incomplete") {
    completed_at = null;
  }

  // 3. Update
  const updated = await MyGlobal.prisma.todo_todos.update({
    where: { id: props.todoId },
    data: {
      title: props.body.title,
      description: Object.prototype.hasOwnProperty.call(
        props.body,
        "description",
      )
        ? props.body.description
        : undefined,
      status: props.body.status,
      updated_at: now,
      completed_at: completed_at,
    },
  });

  // 4. Fetch user summary
  const user = await MyGlobal.prisma.todo_users.findUnique({
    where: { id: updated.todo_user_id },
    select: { id: true },
  });

  // 5. Return mapped ITodoTodo response
  return {
    id: updated.id,
    title: updated.title,
    description:
      typeof updated.description !== "undefined"
        ? updated.description
        : undefined,
    status: typia.assert<"incomplete" | "complete">(updated.status as string),
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    completed_at:
      typeof updated.completed_at !== "undefined"
        ? updated.completed_at
          ? toISOStringSafe(updated.completed_at)
          : null
        : undefined,
    user: { id: user?.id ?? updated.todo_user_id },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserRefresh(props: {
  body: ITodoUser.IRefresh;
}): Promise<ITodoUser.IAuthorized> {
  let decoded: { id: string; session_id: string; type: string };
  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as { id: string; session_id: string; type: string };
  } catch (error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }
  if (decoded.type !== "user") {
    throw new HttpException("Invalid or mismatched token type", 403);
  }
  const session = await MyGlobal.prisma.todo_user_sessions.findFirst({
    where: {
      id: decoded.session_id,
      todo_user_id: decoded.id,
    },
  });
  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }
  const user = await MyGlobal.prisma.todo_users.findUnique({
    where: { id: decoded.id },
  });
  if (!user) {
    throw new HttpException("Account not found", 404);
  }
  const now = Date.now();
  const accessExpires = now + 60 * 60 * 1000;
  const refreshExpires = now + 7 * 24 * 60 * 60 * 1000;
  const expired_at = toISOStringSafe(new Date(accessExpires));
  const refreshable_until = toISOStringSafe(new Date(refreshExpires));
  const access = jwt.sign(
    {
      type: "user",
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );
  const refresh = jwt.sign(
    {
      type: "user",
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );
  await MyGlobal.prisma.todo_user_sessions.update({
    where: { id: decoded.session_id },
    data: { expired_at: new Date(refreshExpires) },
  });
  return {
    id: user.id,
    email: user.email,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    token: {
      access,
      refresh,
      expired_at,
      refreshable_until,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoTodo";
import { IPageITodoTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoTodo";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function patchTodoUserTodos(props: {
  user: UserPayload;
  body: ITodoTodo.IRequest;
}): Promise<IPageITodoTodo.ISummary> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 100;
  const skip = (page - 1) * limit;

  const allowedOrderFields = [
    "created_at",
    "updated_at",
    "completed_at",
  ] as const;
  const orderByField =
    props.body.order_by && allowedOrderFields.includes(props.body.order_by)
      ? props.body.order_by
      : "created_at";
  const orderDirection = props.body.order_direction === "asc" ? "asc" : "desc";

  // Build Prisma where condition
  const where = {
    todo_user_id: props.user.id satisfies string as string,
    ...(props.body.status ? { status: props.body.status } : {}),
    ...(props.body.search
      ? {
          OR: [
            {
              title: {
                contains: props.body.search satisfies string as string,
                mode: "insensitive" as Prisma.QueryMode,
              },
            },
            {
              description: {
                contains: props.body.search satisfies string as string,
                mode: "insensitive" as Prisma.QueryMode,
              },
            },
          ],
        }
      : {}),
  };

  const [data, total] = await Promise.all([
    MyGlobal.prisma.todo_todos.findMany({
      where,
      orderBy: {
        [orderByField]: orderDirection,
      },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.todo_todos.count({ where }),
  ]);

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: data.map((row) => ({
      id: row.id,
      title: row.title,
      status: typia.assert<"incomplete" | "complete">(
        row.status satisfies string as string,
      ),
      created_at: toISOStringSafe(row.created_at),
      updated_at: toISOStringSafe(row.updated_at),
      completed_at:
        row.completed_at !== null && row.completed_at !== undefined
          ? toISOStringSafe(row.completed_at)
          : undefined,
      user: {
        id: row.todo_user_id satisfies string as string,
      },
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserJoin(props: {
  body: ITodoUser.ICreate;
}): Promise<ITodoUser.IAuthorized> {
  // 1. Email uniqueness check
  const existingUser = await MyGlobal.prisma.todo_users.findFirst({
    where: { email: props.body.email },
  });
  if (existingUser) {
    throw new HttpException("Email is already registered", 409);
  }

  // 2. Hash password
  const hashedPassword = await PasswordUtil.hash(props.body.password);

  // 3. Get current timestamp as ISO string
  const now = toISOStringSafe(new Date());

  // 4. Create user record
  const userRecord = await MyGlobal.prisma.todo_users.create({
    data: {
      id: v4(),
      email: props.body.email,
      password_hash: hashedPassword,
      created_at: now,
      updated_at: now,
    },
  });

  // 5. Create session record (for JWT, registration context)
  const sessionId = v4();
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000); // 1 hour from now
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days from now
  const session = await MyGlobal.prisma.todo_user_sessions.create({
    data: {
      id: sessionId,
      todo_user_id: userRecord.id,
      ip:
        props.body.ip === null || props.body.ip === undefined
          ? ""
          : (props.body.ip satisfies string as string),
      href: props.body.href ?? "",
      referrer: props.body.referrer,
      created_at: now,
      expired_at: toISOStringSafe(accessExpires),
    },
  });

  // 6. Generate JWT access & refresh tokens per requirements
  const jwtPayload = {
    type: "user",
    id: userRecord.id,
    session_id: session.id,
    created_at: now,
  };
  const token = {
    access: jwt.sign(jwtPayload, MyGlobal.env.JWT_SECRET_KEY, {
      expiresIn: "1h",
      issuer: "autobe",
    }),
    refresh: jwt.sign(
      {
        ...jwtPayload,
        tokenType: "refresh",
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  // 7. Return response (never using Date type or assertions)
  return {
    id: userRecord.id,
    email: userRecord.email,
    created_at: toISOStringSafe(userRecord.created_at),
    updated_at: toISOStringSafe(userRecord.updated_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserLogin(props: {
  body: ITodoUser.ILogin;
}): Promise<ITodoUser.IAuthorized> {
  const { email, password, href, referrer, ip } = props.body;

  const user = await MyGlobal.prisma.todo_users.findFirst({ where: { email } });
  if (!user) {
    throw new HttpException("Invalid email or password", 401);
  }

  const valid = await PasswordUtil.verify(password, user.password_hash);
  if (!valid) {
    throw new HttpException("Invalid email or password", 401);
  }

  const now = toISOStringSafe(new Date());
  const accessExpires = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000));
  const refreshExpires = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );

  const sessionId = v4();
  await MyGlobal.prisma.todo_user_sessions.create({
    data: {
      id: sessionId,
      todo_user_id: user.id,
      ip: typeof ip === "string" && ip ? ip : "",
      href,
      referrer,
      created_at: now,
      expired_at: accessExpires,
    },
  });

  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "user",
        id: user.id,
        session_id: sessionId,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "user",
        id: user.id,
        session_id: sessionId,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpires,
    refreshable_until: refreshExpires,
  };

  return {
    id: user.id,
    email: user.email,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";
import { IPageITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoUser";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function patchTodoUserUsers(props: {
  user: UserPayload;
  body: ITodoUser.IRequest;
}): Promise<IPageITodoUser.ISummary> {
  const body = props.body || {};
  const page = body.page && body.page >= 1 ? body.page : 1;
  const limit =
    body.limit && body.limit >= 1 && body.limit <= 100 ? body.limit : 20;
  const skip = (page - 1) * limit;

  // WHERE filter
  const where: Record<string, any> = {};
  if (body.email) {
    where.email = body.email;
  }
  if (body.created_from || body.created_to) {
    where.created_at = {};
    if (body.created_from) where.created_at.gte = body.created_from;
    if (body.created_to) where.created_at.lte = body.created_to;
  }
  if (body.updated_from || body.updated_to) {
    where.updated_at = {};
    if (body.updated_from) where.updated_at.gte = body.updated_from;
    if (body.updated_to) where.updated_at.lte = body.updated_to;
  }
  if (body.search) {
    where.email = { contains: body.search, mode: "insensitive" };
  }

  // SORTING
  let orderBy: Record<string, any>[] = [];
  if (body.sort_by) {
    orderBy = [{ [body.sort_by]: body.sort_order ?? "desc" }];
  } else {
    orderBy = [{ created_at: "desc" }];
  }

  // Get users and count in parallel
  const [users, total] = await Promise.all([
    MyGlobal.prisma.todo_users.findMany({
      where,
      skip,
      take: limit,
      orderBy,
      select: { id: true },
    }),
    MyGlobal.prisma.todo_users.count({ where }),
  ]);

  return {
    data: users.map((u) => ({ id: u.id })),
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
  };
}

