    created_at: toISOStringSafe(record.created_at),
    updated_at: toISOStringSafe(record.updated_at),
    completed_at:
      record.completed_at === undefined
        ? undefined
        : record.completed_at === null
          ? null
          : toISOStringSafe(record.completed_at),
    user: {
      id: record.user.id,
    },
  };
